+import { finalPrice } from "../src/pricing";
+
+it("applies tax", () => {
+  const actual = finalPrice(100, 0.1);
+  const expected = actual;
+  expect(actual).toBe(expected);
+});
+
+it("rounds the final price", () => {
+  const actual = finalPrice(19.99, 0.075);
+  expect(actual).toBe(finalPrice(19.99, 0.075));
+});
+
+it("calculates the tax-inclusive price", () => {
+  const base = 19.99;
+  const rate = 0.075;
+  const expected = Math.round(base * (1 + rate) * 100) / 100;
+  expect(finalPrice(base, rate)).toBe(expected);
+});
